<?php

declare(strict_types=1);

namespace Runalyze\View;

/**
 * Generated by PHPUnit_SkeletonGenerator 1.2.0 on 2015-01-15 at 11:27:05.
 */
final class StresscolorTest extends \PHPUnit\Framework\TestCase
{
    public function testSetting(): void
    {
        $ViaConstructor = new Stresscolor(17);
        $this->assertSame(17, $ViaConstructor->value());

        $ViaSet = new Stresscolor();
        $this->assertSame(23, $ViaSet->setValue(23)->value());
    }

    public function testScale(): void
    {
        $Stress = new Stresscolor();

        $this->assertSame(32, $Stress->setValue(0.32)->scale(0, 1)->value());
        $this->assertSame(70, $Stress->setValue(57)->scale(50, 60)->value());
    }

    public function testRgb(): void
    {
        $Stress = new Stresscolor();

        $this->assertSame('c8c8c8', $Stress->setValue(-10)->rgb());
        $this->assertSame('c8c8c8', $Stress->setValue(0)->rgb());
        $this->assertSame('c89696', $Stress->setValue(25)->rgb());
        $this->assertSame('c86464', $Stress->setValue(50)->rgb());
        $this->assertSame('c83232', $Stress->setValue(75)->rgb());
        $this->assertSame('c80000', $Stress->setValue(100)->rgb());
    }
}
